// Functional AN3155 command service. This is not instruction execution of ST ROM.
export function bootRange(r,a,n){return Number.isInteger(a)&&n>0&&(a>=0x08000000&&a+n<=0x08000000+r.board.flashSize||a>=0x20000000&&a+n<=0x20000000+r.board.ram);}
export function bootWrite(r,address,bytes){if(!bootRange(r,address,bytes.length))return false;const e=r.exports,c=r.cpu,width=r.board.cpu==='cortex-m4f'||address>=0x20000000?1:2;if(address%width||bytes.length%width)return false;e.boot_wait(c);e.flash_clear_status(c,255);e.flash_program_width(c,width);let ok=true;try{for(let i=0;i<bytes.length;i+=width){e.boot_wait(c);ok=!!e.memory_write(c,address+i,width===1?bytes[i]:bytes[i]|bytes[i+1]<<8,width)&&ok;if(e.flash_status(c)&11){ok=false;break;}}e.boot_wait(c);return ok&&!(e.flash_status(c)&11);}finally{e.flash_program_width(c,0);}}
function options(s,mode,pages=[]){const f=s.r.flash,e=s.r.exports,c=s.r.cpu;if(f.rdp()===2)return false;e.boot_wait(c);if(s.f4){if(f.activeOPT&0x80000000)return false;let opt=f.storedOPT;if(mode==='wp')for(const page of pages)opt&=~(1<<(16+page));if(mode==='wup')opt|=0x0fff0000;if(mode==='rp')opt=(opt&~0xff00)|0x5500;if(mode==='rup')opt=0x0fffaaec;f.storedOPT=opt>>>0;}else{const o=f.option,set=(i,v)=>{o[i]=v;o[i+1]=v^255;};if(mode==='wp'){let mask=f.writeMask();for(const page of pages)mask&=~(1<<(page>>>2));for(let i=0;i<4;i++)set(8+i*2,mask>>>(8*i)&255);}if(mode==='wup')for(let i=8;i<16;i+=2)set(i,255);if(mode==='rp')set(0,0);if(mode==='rup'){for(let i=0;i<16;i+=2)set(i,i===0?0xa5:255);}}
 if(mode==='rup'&&f.rdp()){e.flash_protection_clear(c);e.flash_erase(c,0,s.r.board.flashSize);e.boot_wait(c);}s.requestReset(7);return true;}
export function bootByte(s,byte){
 const r=s.r,b=s.bootState,ack=()=>{r.serial+='\x79';},nak=()=>{r.serial+='\x1f';},out=bytes=>{r.serial+=String.fromCharCode(...bytes);},command=()=>{b.stage='command';b.data=[];};
 if(!Number.isInteger(byte)||byte<0||byte>255)throw Error('Boot USART verisi bayt olmalı.');
 if(b.stage==='sync'){if(byte===0x7f){ack();command();}return;}
 if(b.stage==='command'){b.command=byte;b.stage='complement';return;}
 if(b.stage==='complement'){
  const commands=[0,1,2,0x11,0x21,0x31,0x43,0x44,0x63,0x73,0x82,0x92];if((b.command^byte)!==255||!commands.includes(b.command)||r.flash.rdp()&&![0,1,2,0x92].includes(b.command)){nak();command();return;}ack();
  const version=s.f4?0x31:0x22;if(b.command===0){out([commands.length,version,...commands]);ack();command();}else if(b.command===1){out([version,0,0]);ack();command();}else if(b.command===2){const id=s.f4?s.r.board.family==='f411'?0x431:s.r.board.flashSize<=262144?0x423:0x433:s.r.board.flashSize===32768?0x412:0x410;out([1,id>>>8,id&255]);ack();command();}else if([0x73,0x82,0x92].includes(b.command)){options(s,{0x73:'wup',0x82:'rp',0x92:'rup'}[b.command])?ack():nak();command();}else{b.data=[];b.stage=[0x43,0x44].includes(b.command)?'erase':b.command===0x63?'protect':'address';}return;
 }
 b.data.push(byte);if(b.data.length>1027){nak();command();return;}
 if(b.stage==='address'&&b.data.length===5){const d=b.data,a=(d[0]*0x1000000+(d[1]<<16)+(d[2]<<8)+d[3])>>>0;if((d[0]^d[1]^d[2]^d[3])!==d[4]||!bootRange(r,a,b.command===0x21?8:1)){nak();command();return;}b.address=a;b.data=[];ack();b.stage=b.command===0x11?'read':b.command===0x31?'write':'command';if(b.command===0x21){s.goAddress=a;s.requestReset(7);}}
 else if(b.stage==='read'&&b.data.length===2){const[n,check]=b.data;if((n^check)!==255||!bootRange(r,b.address,n+1))nak();else{ack();out(r.readMemory(b.address,n+1));}command();}
 else if(b.stage==='write'&&b.data.length===b.data[0]+3){const d=b.data;if(d.reduce((a,v)=>a^v,0)||!bootWrite(r,b.address,d.slice(1,-1)))nak();else ack();command();}
 else if(b.stage==='protect'&&b.data.length===b.data[0]+3){const d=b.data,pages=d.slice(1,-1),valid=pages.every(p=>s.f4?r.flash.sector(p)[0]<r.board.flashSize:p*1024<r.board.flashSize);if(d.reduce((a,v)=>a^v,0)||!valid||!options(s,'wp',pages))nak();else ack();command();}
 else if(b.stage==='erase'){
  const d=b.data,extended=b.command===0x44;if(extended&&d.length<3||!extended&&d.length<2)return;const count=extended?(d[0]<<8)|d[1]:d[0],mass=count===(extended?65535:255),needed=mass?(extended?3:2):(extended?3+(count+1)*2:count+3);if(d.length<needed)return;if(d.length!==needed||(mass&&!extended?d[1]!==0:!!d.reduce((a,v)=>a^v,0))){nak();command();return;}const ranges=[];if(mass)ranges.push([0,r.board.flashSize]);else for(let i=0;i<=count;i++){const page=extended?(d[2+i*2]<<8)|d[3+i*2]:d[i+1];ranges.push(s.f4?r.flash.sector(page):[page*1024,1024]);}if(ranges.some(([a,n])=>a<0||a+n>r.board.flashSize)){nak();command();return;}const e=r.exports;let ok=true;e.flash_clear_status(r.cpu,255);for(const[a,n]of ranges){e.boot_wait(r.cpu);ok=!!e.flash_erase(r.cpu,a,n)&&ok;}e.boot_wait(r.cpu);ok?ack():nak();command();
 }
}
